    layer: 'National Parks & Reserves',
    mapFeatureId: 'anomaly-National-Parks---Reserves-19',
    images: ['https://upload.wikimedia.org/wikipedia/commons/b/bf/A045%2C_Glacier_Bay_National_Park%2C_Alaska%2C_USA%2C_Johns_Hopkins_Glacier%2C_2002.jpg'],
